```python
def max_length(list_of_lists):
    if not list_of_lists:
        return (0, [])
    max_len = len(max(list_of_lists, key=len))
    max_lists = [sublist for sublist in list_of_lists if len(sublist) == max_len]
    return (max_len, max_lists)
```

```python
def Sum_of_Inverse_Divisors(n, m):
    total_sum = 0
    for i in range(1, min(n, m) + 1):
        if n % i == 0 and m % i == 0:
            total_sum += 1 / i
    return total_sum

