def lobb_num(ln, m):
    def factorial(n):
        if n == 0:
            return 1
        else:
            return n * factorial(n-1)

    lobb_number = 1
    for i in range(m):
        lobb_number = (obb_number * (ln - i)) // (i + 1)
    return lobb_number
```

