def get_ludic(n):
    if n < 1:
        return []

    lucid_numbers = [1]
    i = 2
    while i <= n:
        if sum(digit for digit in str(i)) % 2 == 0:
            lucid_numbers.append(i)
        i += 1

    return lucid_numbers
```

