```python
def magic_square_test(matrix):
    n = len(matrix)
    if n != 4 or any(len(row) != n for row in matrix):
        return False

    # Calculate the sum of the first row
    target_sum = sum(matrix[0])

    # Check rows
    for i in range(n):
        if sum(matrix[i]) != target_sum:
            return False

    # Check columns
    for j in range(n):
        if sum(matrix[i][j] for i in range(n)) != target_sum:
            return False

    # Check diagonals
    if sum(matrix[i][i] for i in range(n)) != target_sum or sum(matrix[i][n-i-1] for i in range(n)) != target_sum:
        return False

    return True
```

